local _c=string.char local _f=math.floor
local _A="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local _M={}for i=1,#_A do _M[_A:sub(i,i)]=i-1 end
local function _d(s)
    s=s:gsub("[^A-Za-z0-9+/]","")
    local o,buf,bits={},0,0
    for i=1,#s do
        local v=_M[s:sub(i,i)] if v then buf=buf*64+v; bits=bits+6
            if bits>=8 then bits=bits-8; o[#o+1]=_c(_f(buf/(2^bits))%256); buf=buf%(2^bits) end
        end
    end
    return table.concat(o)
end
